        .cx-custom-item-row > div { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 8px; align-items: center; width: 100%; }
        .cx-btn-icon { background: rgba(217, 119, 6, 0.15); border: 1px solid var(--cx-gold-main); color: var(--cx-gold-light); border-radius: 4px; width: 34px; height: 34px; cursor: pointer; transition: all 0.3s; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
