        .cx-btn-icon.danger { border-color: var(--cx-danger); color: var(--cx-danger); background: rgba(239, 68, 68, 0.1); }

        .cx-fabao-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 15px; width: 100%; margin-top: 5px; }
        .cx-fabao-card { background: rgba(30, 27, 75, 0.4); border: 1px solid var(--cx-glass-border); padding: 15px; border-radius: 4px; cursor: pointer; transition: all 0.3s ease; display: flex; flex-direction: column; gap: 8px; position: relative; overflow: hidden; }
