        .cx-fabao-card.selected { border-color: var(--cx-gold-light); background: rgba(217, 119, 6, 0.15); box-shadow: 0 0 15px rgba(217, 119, 6, 0.4); }
        .cx-fabao-header { display: flex; align-items: center; gap: 12px; }
        .cx-fabao-icon { width: 35px; height: 35px; background: #030712; border: 1px solid var(--cx-gold-main); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--cx-gold-main); font-size: 1rem; flex-shrink: 0; }
        .cx-fabao-card.selected .cx-fabao-icon { background: var(--cx-gold-dark); color: #fff; border-color: #fff; }
        .cx-fabao-name { font-size: 1.1rem; color: var(--cx-text-title); font-weight: 900; margin:0; }
        .cx-fabao-desc { font-size: 0.85rem; color: var(--cx-text-body); line-height: 1.5; }

        .cx-btn-high { padding: 14px 45px; background: rgba(3, 7, 18, 0.8); border: 1px solid var(--cx-gold-main); color: var(--cx-gold-light); font-family: 'Noto Serif SC', serif; font-size: 1.15rem; font-weight: 900; letter-spacing: 4px; cursor: pointer; transition: all 0.3s ease; box-shadow: 0 8px 20px rgba(0,0,0,0.6); border-radius: 4px; display: flex; align-items: center; gap: 10px; justify-content: center; }
        .cx-btn-high:hover:not(:disabled) { background: rgba(217, 119, 6, 0.2); color: #fff; border-color: var(--cx-gold-light); box-shadow: 0 0 20px rgba(217, 119, 6, 0.4); transform: translateY(-2px); }

        .cx-toast { position: absolute; top: 80px; left: 50%; transform: translateX(-50%) translateY(-20px); background: rgba(3,7,18,0.95); color: var(--cx-gold-light); padding: 15px 35px; border-radius: 4px; border: 1px solid var(--cx-gold-dark); z-index: 1000; opacity: 0; pointer-events: none; transition: all 0.3s; font-weight: bold; font-size: 1.1rem; box-shadow: 0 10px 30px rgba(0,0,0,0.8); max-width: 90vw; text-align: center; }

        /* ================= 📱 手机端究极适配 (核心响应式) ================= */
        @media (max-width: 768px) {
            /* 1. 打破图片撑开限制，强制手机端变为竖屏容器 */
            .cx-launcher {
                height: 85vh; /* 赋予竖版独立高度 */
                min-height: 600px;
                max-height: 850px;
            }
            /* 2. 底图智能裁剪填满竖版空间，拒绝被压扁 */
            .cx-base-bg-img {
                position: absolute;
                width: 100%;
                height: 100%;
                object-fit: cover;
                object-position: 70% center; /* 稍微偏移聚焦图的重点 */
            }

            /* 基础UI压缩 */
            .home-content { left: 5%; width: 90%; text-align: center; align-items: center; }
            .home-menu-btn { width: 100%; justify-content: center; border-radius: 8px; border-left: 1px solid rgba(217, 119, 6, 0.3); border-bottom: 4px solid var(--cx-gold-main); }
            .home-menu-btn:hover { padding-left: 30px; transform: translateY(-5px); border-bottom-color: var(--cx-gold-light); }
            .sub-page-content { padding: 60px 15px 15px 15px; }

            /* 详情与表单重构，修复横向溢出问题 */
            .cx-modal { padding: 10px; }
            .cx-modal-box { padding: 25px 15px; width: 100%; max-width: 100vw; }
            .cx-form-grid { grid-template-columns: 1fr; gap: 15px; }

            /* 确保内部小并排元素能够自适应换行，避免撑破容器 */
            .cx-custom-item-row input.cx-form-input { flex: 1 1 40% !important; min-width: 80px !important; }

            .intro-text-box { padding: 25px 20px; width: 95%; }
            .cx-detail-box { width: 95%; height: 85%; }
            .cx-detail-header { padding: 20px 20px; flex-direction: column; gap: 15px; }
            .cx-detail-content { padding: 20px; }
            .cx-btn-close-detail { position: absolute; top: 15px; left: 15px; right: auto; margin-top: 0; }

            /* 角色立绘变为上下结构 */
            .cx-char-modal { padding: 20px; }
            .cx-char-box { flex-direction: column; height: 95%; overflow-y: auto; }
            .cx-char-left { width: 100%; height: 45%; border-right: none; border-bottom: 1px solid var(--cx-glass-border); z-index: 1; flex-shrink: 0; }
            .cx-char-left::after { background: linear-gradient(0deg, #030712 0%, transparent 50%); }
