            .cx-char-header { flex-direction: column; text-align: center; gap: 10px; margin-bottom: 20px; padding-bottom: 15px; }
            .cx-music-wrapper { top: 15px; right: 15px; }

            /* 轮盘导航按钮向内缩，防止超出屏幕 */
