            .cx-btn-free-start { right: 5px; transform: none; padding: 10px 15px; font-size: 0.9rem; }
            .cx-btn-random:hover { transform: translateY(-2px); }
            .cx-btn-free-start:hover { transform: translateY(-2px); }
        }
    </style>
</head>
