<script>
    // ================= 核心切页逻辑 =================
    function switchView(viewId) {
        const target = document.getElementById(viewId) || document.getElementById('home-view');
        document.querySelectorAll('.view-container').forEach(el => el.style.display = 'none');
        if (target) target.style.display = 'block';
        if(target && target.id === 'carousel-view' && typeof updateCarousel === 'function') {
            setTimeout(updateCarousel, 50);
        }
    }


    (function() {
        // 点击黑色背景关闭模态框
        $('.cx-char-modal, .cx-detail-page, .cx-modal').on('click', function(e) {
            if (e.target === this) {
                $(this).removeClass('show');
            }
        });

        $('#btn-close-char').on('click', function() { document.getElementById('cx-char-modal').classList.remove('show'); });
        $('#btn-close-detail').on('click', function() { document.getElementById('cx-detail-page').classList.remove('show'); });
        $('#btn-close-freestart').on('click', function() { document.getElementById('cx-freestart-modal').classList.remove('show'); });

        // ================= 音乐播放器 =================
        const bgm = document.getElementById('cx-bgm');
        const btnToggle = $('#btn-music-toggle');
        const musicMenu = $('#music-menu');
        const musicItems = $('.cx-music-item');
        const progressBar = document.getElementById('bgm-progress');
        const timeDisplay = document.getElementById('bgm-curr-time');
        let isPlaying = false;

        btnToggle.on('click', function(e) {
            e.stopPropagation();
            musicMenu.toggleClass('show');
        });

        $(document).on('click', function(e) {
            if (!$(e.target).closest('.cx-music-wrapper').length) {
                musicMenu.removeClass('show');
            }
        });

        function formatTime(seconds) {
            if(isNaN(seconds)) return "0:00";
            const m = Math.floor(seconds / 60);
            const s = Math.floor(seconds % 60);
            return `${m}:${s < 10 ? '0' : ''}${s}`;
        }

        musicItems.on('click', function(e) {
            e.stopPropagation();
            const src = $(this).data('src');
            if($(this).hasClass('active')) {
                if (isPlaying) { bgm.pause(); btnToggle.removeClass('playing'); }
                else { bgm.play().catch(e => console.log("播放失败", e)); btnToggle.addClass('playing'); }
                isPlaying = !isPlaying;
            } else {
                musicItems.removeClass('active'); $(this).addClass('active');
                bgm.src = src; bgm.load(); bgm.play().catch(e => console.log("播放失败", e));
                btnToggle.addClass('playing'); isPlaying = true;
            }
        });

        bgm.addEventListener('timeupdate', () => {
            if (bgm.duration) {
                progressBar.value = (bgm.currentTime / bgm.duration) * 100;
                timeDisplay.innerText = formatTime(bgm.currentTime);
            }
        });

