        window.updateCarousel = function() {
            const containerHeight = document.querySelector('.cx-3d-scene').clientHeight;
            const cardHeight = containerHeight * 0.65;
            const cardWidth = cardHeight * (2 / 3);

            // 移动端智能缩小轮盘半径，防止卡片超出屏幕
            const radiusOffset = window.innerWidth < 768 ? 70 : 150;
            const radius = Math.round((cardWidth / 2) / Math.tan(Math.PI / total)) + radiusOffset;

            $cards.each(function(index) {
                let angle = currentAngle + (index * angleStep);
                let rad = angle * (Math.PI / 180);
                let x = Math.sin(rad) * radius;
                let z = Math.cos(rad) * radius - radius;
                let normalizedAngle = angle % 360;
                if (normalizedAngle < 0) normalizedAngle += 360;
                let isFront = (normalizedAngle < 5 || normalizedAngle > 355);
                let scale = 0.6 + ((z + radius) / (radius * 2)) * 0.4;

                if (isFront) { scale = 1.1; frontIndex = index; }

                $(this).css({
                    'transform': `translate(-50%, -50%) translateX(${x}px) translateZ(${z}px) scale(${scale})`,
                    'z-index': Math.round(z + radius)
                });
                if (isFront) $(this).addClass('is-front');
                else $(this).removeClass('is-front');
            });
        };

