            const clickedIndex = $(this).data('index');

            if (clickedIndex === frontIndex) {
                const charData = characters[clickedIndex];
                cmFront.src = charData.front;
                cmAvatar.src = charData.avatar;
                cmName.innerText = charData.name;
                cmSect.innerText = charData.sect;
                cmTitle.innerText = charData.title;
                cmDesc.innerText = charData.desc;
                cmBtnSelect.dataset.id = charData.id;
                charModal.classList.add('show');
            } else {
                isAnimating = true;
                let diff = frontIndex - clickedIndex;
                if (diff > total / 2) diff -= total;
                if (diff < -total / 2) diff += total;
                currentAngle += diff * angleStep;
                updateCarousel();
                setTimeout(() => { isAnimating = false; }, 500);
            }
        });

