            ENTRY_COMMENT: "USER档案",

            async getTargetEntry() {
                if (typeof getLorebookEntries !== 'function') {
                    throw new Error("世界书读取接口不可用：getLorebookEntries 未加载");
                }
                const tried = [];
                for (const bookName of this.LOREBOOK_NAMES) {
