                await this.setEntryEnabledByComment("小索【人设】", shouldEnableXiaoSuo);
                return shouldEnableXiaoSuo;
            },

            async saveUserProfile(profileData, entryToUpdate) {
                const originalContent = entryToUpdate.content;
                const marker = "【苍玄界·" + "{{" + "user" + "}}" + "档案】";
                const markerIndex = originalContent.indexOf(marker);

                if (markerIndex === -1) {
                    throw new Error(`世界书条目格式错误，未找到锚点"${marker}"`);
                }

                const headerContent = originalContent.substring(0, markerIndex + marker.length);

                const extractOld = (regex, fallback = "无") => {
                    const match = originalContent.match(regex);
                    return match && match[1].trim() !== "" ? match[1].trim() : fallback;
                };

                const currentName = extractOld(/【姓名】[\s\S]*?姓名：([^\n]*)/, "");
                const currentGender = extractOld(/【性别】[\s\S]*?性别：([^\n]*)/);
                const currentRealm = extractOld(/【初始境界】[\s\S]*?境界：([^\n]*)/);
                const currentFabaoName = extractOld(/【随身信物】[\s\S]*?名称：([^\n]*)/);
                const currentFabaoDesc = extractOld(/【随身信物】[\s\S]*?描述：([^\n]*)/);
                const currentHistory = extractOld(/【过往经历】[\s\S]*?描述：([\s\S]*?)(?=\n\n<\/rule>|<\/rule>|$)/);

                const newName = profileData.name !== undefined && profileData.name !== "" ? profileData.name : currentName;
                const newGender = profileData.gender !== undefined ? profileData.gender : currentGender;
                const newRealm = profileData.realm !== undefined ? profileData.realm : currentRealm;
                const newHistory = profileData.history !== undefined && profileData.history !== "" ? profileData.history : currentHistory;

                let newFabaoName = currentFabaoName;
                let newFabaoDesc = currentFabaoDesc;
                if (profileData.fabao) {
                    if (profileData.fabao.id === "none") {
                        newFabaoName = "无";
                        newFabaoDesc = "无";
                    } else {
                        newFabaoName = profileData.fabao.name;
                        newFabaoDesc = profileData.fabao.desc;
                    }
                }

                let npcText = "无";
                if (profileData.npcs && profileData.npcs.length > 0) {
                    npcText = "";
                    profileData.npcs.forEach(n => {
                        npcText += `- 姓名：${n.name} | 身份：${n.sect} | 境界：${n.realm} | 关系：${n.relation}\n  描述：${n.desc}\n`;
                    });
                    npcText = npcText.trim();
                }

                const newProfileContent = `\n\n【姓名】\n姓名：${newName}\n\n【性别】\n性别：${newGender}\n\n【初始境界】\n境界：${newRealm}\n\n【随身信物】\n名称：${newFabaoName}\n描述：${newFabaoDesc}\n\n【同行道友】\n记录：\n${npcText}\n\n【过往经历】\n描述：${newHistory}\n\n</rule>`;

                const finalContent = headerContent + newProfileContent;

                if (typeof setLorebookEntries !== 'function') {
                    throw new Error("世界书写入接口不可用：setLorebookEntries 未加载");
                }
                const payload = { content: finalContent, comment: this.ENTRY_COMMENT };
                if (entryToUpdate.uid !== undefined) payload.uid = entryToUpdate.uid;
                if (entryToUpdate.id !== undefined) payload.id = entryToUpdate.id;
                await setLorebookEntries(entryToUpdate.__bookName, [payload]);
            }
        };

