scripts.content:
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

const ALL_REALMS = [
  "炼气一层", "炼气二层", "炼气三层", "炼气四层", "炼气五层", "炼气六层", "炼气七层", "炼气八层", "炼气九层",
  "筑基一层", "筑基二层", "筑基三层", "筑基四层", "筑基五层", "筑基六层", "筑基七层", "筑基八层", "筑基九层",
  "金丹一层", "金丹二层", "金丹三层", "金丹四层", "金丹五层", "金丹六层", "金丹七层", "金丹八层", "金丹九层",
  "元婴一层", "元婴二层", "元婴三层", "元婴四层", "元婴五层", "元婴六层", "元婴七层", "元婴八层", "元婴九层",
  "化神一层", "化神二层", "化神三层", "化神四层", "化神五层", "化神六层", "化神七层", "化神八层", "化神九层",
  "炼虚一层", "炼虚二层", "炼虚三层", "炼虚四层", "炼虚五层", "炼虚六层", "炼虚七层", "炼虚八层", "炼虚九层",
  "合体一层", "合体二层", "合体三层", "合体四层", "合体五层", "合体六层", "合体七层", "合体八层", "合体九层",
  "大乘一层", "大乘二层", "大乘三层", "大乘四层", "大乘五层", "大乘六层", "大乘七层", "大乘八层", "大乘九层",
  "渡劫一层", "渡劫二层", "渡劫三层", "渡劫四层", "渡劫五层", "渡劫六层", "渡劫七层", "渡劫八层", "渡劫九层", "半步真仙", "真仙大成"
];

const MAIN_NPC_NAMES = [
    "沈慕微",
    "江念",
    "欧阳诚",
    "萧天衍",
    "谢忘生",
    "药芷若",
    "叶段英",
    "慕海棠",
    "颂长风",
    "印唯心",
    "妖九烟",
    "阎冥",
    "冷小凝",
    "姜昭昭",
    "苏酒儿",
    "姜澄鸢",
    "红",
    "雪照宁",
    "潮听澜",
    "小索"
  ];

const isMainNpcName = name => MAIN_NPC_NAMES.includes(String(name || ''));
const normalizeFavor = value => _.clamp(Number(value) || 0, 0, 100);

export const Schema = z.object({
  主角状态: z.object({
    修为: z.object({
      当前境界: z.string().prefault('待推演'),
      进度百分比: z.coerce.number().prefault(0),
      当前状态描述: z.string().prefault('境界稳固。')
    }).transform(cultivation => {
      if (cultivation.进度百分比 >= 100) {
        let currentIndex = ALL_REALMS.indexOf(cultivation.当前境界);
        if (currentIndex !== -1 && currentIndex < ALL_REALMS.length - 1) {
          cultivation.当前境界 = ALL_REALMS[currentIndex + 1];
          cultivation.进度百分比 = cultivation.进度百分比 - 100;
          if (cultivation.进度百分比 >= 100) cultivation.进度百分比 = 99;
        } else {
          cultivation.进度百分比 = 99;
        }
      } else if (cultivation.进度百分比 < 0) {
        cultivation.进度百分比 = 0;
      }
      return cultivation;
    }).prefault({ 当前境界: '待推演', 进度百分比: 0, 当前状态描述: '待推演' }),

    灵石钱包: z.object({
      上品灵石: z.coerce.number().prefault(0),
      中品灵石: z.coerce.number().prefault(0),
      下品灵石: z.coerce.number().prefault(0),
      钱包预警: z.string().prefault('身无分文')
    }).transform(wallet => {
      // 1. 借位补齐下品
      while (wallet.下品灵石 < 0 && wallet.中品灵石 > 0) {
        wallet.中品灵石 -= 1;
        wallet.下品灵石 += 100;
      }
      while (wallet.下品灵石 < 0 && wallet.上品灵石 > 0) {
        wallet.上品灵石 -= 1;
        wallet.下品灵石 += 10000;
      }
      // 2. 借位补齐中品
      while (wallet.中品灵石 < 0 && wallet.上品灵石 > 0) {
        wallet.上品灵石 -= 1;
        wallet.中品灵石 += 100;
      }
      // 3. 自动进位（逢百进一）
      if (wallet.下品灵石 >= 100) {
         let addM = Math.floor(wallet.下品灵石 / 100);
         wallet.中品灵石 += addM;
         wallet.下品灵石 %= 100;
      }
      if (wallet.中品灵石 >= 100) {
         let addH = Math.floor(wallet.中品灵石 / 100);
         wallet.上品灵石 += addH;
         wallet.中品灵石 %= 100;
      }
      // 4. 兜底清零防崩
      if (wallet.下品灵石 < 0) wallet.下品灵石 = 0;
      if (wallet.中品灵石 < 0) wallet.中品灵石 = 0;
      if (wallet.上品灵石 < 0) wallet.上品灵石 = 0;
      return wallet;
    }).prefault({ 上品灵石: 0, 中品灵石: 0, 下品灵石: 0, 钱包预警: '身无分文' }),

    个人背包: z.record(
      z.string().describe('物品名'),
      z.object({
        描述: z.string(),
        数量: z.coerce.number()
      })
    ).transform(data => _.pickBy(data, ({ 数量 }) => 数量 > 0)).prefault({})
  }).prefault({}),

  世界系统: z.object({
    当前时间: z.string().describe('修真历年月日时辰').prefault('待推演'),
    当前地址: z.string().describe('剧情当前地址').prefault('待推演'),
    大区域: z.string().describe('EJS世界书主区域定位').prefault('天剑宗'),
    子区域: z.string().describe('EJS世界书子区域定位').prefault('天剑宗'),
    具体地点: z.string().describe('EJS世界书具体地点定位').prefault('祖师祠堂'),
    在场角色: z.string().describe('顿号分隔的当前同场或可直接互动角色名').prefault(''),

    今日运势: z.object({
      宜: z.string().prefault('待推演'),
      忌: z.string().prefault('待推演')
    }).prefault({ 宜: '待推演', 忌: '待推演' }),

    修仙八卦论坛: z.record(
      z.string().describe('热搜标题'),
      z.object({
        标签: z.enum(['热', '新', '荐', '爆', '普通']),
        详情描述: z.string()
      })
    ).prefault({}),

    修仙秘闻: z.record(
      z.string().describe('秘闻简述'),
      z.string().describe('具体内容')
    ).prefault({}),

    随身拍卖行: z.record(
      z.string().describe('商品名'),
      z.object({
        状态标签: z.string(),
        卖家秀: z.string(),
        当前价格: z.string()
      })
    ).prefault({}),

    委托板: z.record(
      z.string().describe('委托标题'),
      z.object({
        分类: z.enum(['日常', '悬赏', '宗门']),
        任务详情: z.string(),
        报酬: z.string()
      })
    ).prefault({})
  }).prefault({}),

  人际交往: z.object({
    最新传讯: z.object({
      发送者: z.string().prefault('无'),
      内容: z.string().prefault('暂无飞剑传书')
    }).prefault({ 发送者: '无', 内容: '暂无飞剑传书' }),

    结识道友录: z.record(
      z.string().describe('主要NPC名字'),
      z.object({
        宗门: z.string().prefault('未知'),
        境界: z.string().prefault('未知'),
        当前所在地: z.string().prefault('未知'),
        好感度数值: z.coerce.number().transform(v => normalizeFavor(v)).prefault(0),
        好感度阶段: z.string().prefault('形同陌路'),
        关系标签: z.string().prefault('初识'),
        新增互动输入: z.string().prefault(''),
        最近互动记录: z.array(z.string()).prefault(['暂无'])
      }).transform(npc => {
        const val = npc.好感度数值;
        if (val < 20) npc.好感度阶段 = '形同陌路';
        else if (val < 40) npc.好感度阶段 = '萍水相逢';
        else if (val < 60) npc.好感度阶段 = '泛泛之交';
        else if (val < 80) npc.好感度阶段 = '相谈甚欢';
        else if (val < 95) npc.好感度阶段 = '莫逆之交';
        else npc.好感度阶段 = '生死相托';

        if (npc.新增互动输入 && npc.新增互动输入.trim() !== '') {
          if (npc.最近互动记录.length === 1 && npc.最近互动记录[0] === '暂无') {
            npc.最近互动记录 = [];
          }
          npc.最近互动记录.unshift(npc.新增互动输入);
          if (npc.最近互动记录.length > 3) {
            npc.最近互动记录 = npc.最近互动记录.slice(0, 3);
          }
          npc.新增互动输入 = '';
        }
        return npc;
      })
    ).prefault({}),

    路遇道友录: z.record(
      z.string().describe('非主要NPC名字'),
      z.object({
        好感度数值: z.coerce.number().transform(v => normalizeFavor(v)).prefault(0),
        关系标签: z.string().prefault('初识')
      }).prefault({ 好感度数值: 0, 关系标签: '初识' })
    ).prefault({}),

    当前接触人物: z.record(
      z.string().describe('主要NPC名字'),
      z.object({
        心情: z.string(),
        心声: z.string()
      })
    ).prefault({})
  }).transform(social => {
    const mainFriends = {};
    const minorFriends = { ...social.路遇道友录 };

    Object.entries(social.结识道友录 || {}).forEach(([name, data]) => {
      if (isMainNpcName(name)) {
        mainFriends[name] = data;
      } else if (name && name !== '无') {
        const existing = minorFriends[name] || {};
        const existingFavor = normalizeFavor(_.get(existing, '好感度数值', 0));
        const migratedFavor = normalizeFavor(_.get(data, '好感度数值', existingFavor));
        const existingRelation = String(_.get(existing, '关系标签', '') || '').trim();
        const migratedRelation = String(_.get(data, '关系标签', '') || '').trim();

        minorFriends[name] = {
          好感度数值: migratedFavor !== 0 || existingFavor === 0 ? migratedFavor : existingFavor,
          关系标签: migratedRelation && (migratedRelation !== '初识' || !existingRelation)
            ? migratedRelation
            : (existingRelation || '初识')
        };
      }
    });

    social.结识道友录 = mainFriends;
    social.路遇道友录 = minorFriends;

    social.当前接触人物 = Object.fromEntries(
      Object.entries(social.当前接触人物 || {}).filter(([name]) => isMainNpcName(name))
    );

    if (social.最新传讯?.发送者 && social.最新传讯.发送者 !== '无' && !isMainNpcName(social.最新传讯.发送者)) {
      social.最新传讯 = { 发送者: '无', 内容: '暂无飞剑传书' };
    }

    return social;
  }).prefault({})
});

