/* ===== 用户输入扫描控制器 =====
 * 蓝灯常驻，@@preprocessing 确保在所有区域控制器之前执行
 * 扫描最后2条消息(含用户和AI)，匹配角色名/地名/势力名
 * 匹配到后加载：角色条目 + 所属宗门/势力条目
 * 结果记录到 _scanActivated 数组，供区域控制器判断是否跳过
 *
 * 互斥规则：扫描优先 → 区域控制器跳过已被扫描激活的条目
 */
if (typeof _scanActivated === 'undefined') var _scanActivated = [];
var _scanText = '';
if (typeof lastUserMessage !== 'undefined' && lastUserMessage) _scanText += lastUserMessage + ' ';
if (typeof lastCharMessage !== 'undefined' && lastCharMessage) _scanText += lastCharMessage + ' ';
function _scanMatch(text, keywords) {
  for (var i = 0; i < keywords.length; i++) {
    if (text.indexOf(keywords[i]) !== -1) return true;
  }
  return false;
}
function _scanActivate(entries) {
  for (var i = 0; i < entries.length; i++) {
    if (_scanActivated.indexOf(entries[i]) === -1) {
      _scanActivated.push(entries[i]);
    }
  }
}
if (_scanText) {
